import {SETUP_GROUPS} from './setup-model.mjs';

const table=(heads,rows)=>`<div class="guide-table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th scope="row"'}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const note=(title,text)=>`<aside class="guide-note"><strong>${title}</strong><p>${text}</p></aside>`;
const code=s=>`<pre><code>${s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}</code></pre>`;
const figure=(id,title,caption,controls='',fallback='')=>`<figure class="guide-figure"><div class="figure-title"><h3>${title}</h3><span>ESEMPIO SINTETICO</span></div>${controls}<canvas id="${id}" role="img" aria-label="${title}. ${caption}">${caption}</canvas><figcaption>${caption}</figcaption>${fallback}</figure>`;
const source=files=>`<p class="guide-source">Implementazione: ${files.map(f=>`<code>${f}</code>`).join(', ')}. File inclusi nell'archivio <a href="./source.zip">Sorgenti</a>.</p>`;

export const GUIDE_CHAPTERS=[
{id:'campo',title:'01 / Procedura tra due heat',tags:'inizio importazione gara allenamento workflow',html:`
<p>GND Race confronta segnali e configurazioni di voli FPV. Il punto di partenza non e un voto al pilota: e una domanda verificabile, per esempio "il residuo ad alta frequenza si ripete?" oppure "la risposta al comando cambia dopo una modifica?". Una differenza nei numeri non dimostra da sola una causa.</p>
<ol><li><strong>Prima del volo:</strong> conserva il backup della configurazione e annota quad, eliche, batteria, eventuali modifiche e condizioni. Un backup acquisito dopo il tuning non descrive necessariamente la heat precedente.</li><li><strong>Importa il log originale</strong> con Importa log. Se contiene piu voli, il decoder li separa. Una heat puo contenere un log oppure soltanto dati manuali; il secondo caso non consente analisi PID.</li><li><strong>Controlla la telemetria:</strong> scale credibili, canali disponibili, avvisi e intervallo. Escludi dal tratto analizzato eventi non pertinenti, come un crash, senza nascondere oscillazioni reali.</li><li><strong>Apri PID / FILTRI</strong> per vedere spettri, contributi e indizi sul singolo asse. Apri Miglioramenti per la priorita di prova e le colonne attuale/consigliato.</li><li><strong>Associa il backup</strong> in Configurazione e qualita del log. Scegli il profilo PID realmente usato e conferma l'associazione. La presenza di un file non prova automaticamente che appartenga al volo.</li><li><strong>Decidi una sola prova.</strong> Risolvi prima problemi meccanici o di margine motori. Non trasformare tutte le righe gialle in una lista di modifiche da applicare insieme.</li><li><strong>Registra un'altra heat confrontabile</strong> e conserva il nuovo backup. In Prima / dopo seleziona la heat precedente e annota cosa hai cambiato. Controlla anche sensazione di guida, oscillazioni e temperatura motori.</li><li><strong>Esporta la sessione</strong> prima di chiudere una giornata di allenamento o cambiare dispositivo. Il salvataggio nel browser non e una copia esterna.</li></ol>
${note('Non e autotune','Le proposte non vengono scritte nella flight controller. Il tool non determina un PID ottimale, non certifica stabilita e non sostituisce una prova controllata. "Nessuna modifica" e un risultato valido.')}
<p>Gli eventuali tempi ufficiali sono inseriti manualmente e riguardano la heat completa. Non esistono calcolo automatico dei giri, settori o classifiche.</p>`},
{id:'flusso',title:'02 / Dal file alla proposta',tags:'architettura pipeline worker dati nativi decimazione',html:`
<p>La stessa Blackbox alimenta due percorsi con risoluzioni diverse. Il lavoro di decodifica avviene in un Web Worker separato dalla pagina. Il browser riceve una heat con telemetria ridotta, orientamenti e aggregati PID; non conserva nell'archivio tutti i frame nativi usati dalla FFT.</p>
<ol class="guide-flow"><li><i data-lucide="file-input"></i><strong>BBL / CSV</strong><span>Controllo formato, timestamp, scale</span></li><li><i data-lucide="activity"></i><strong>Frame nativi</strong><span>Assetto e finestre PID prima della riduzione</span></li><li><i data-lucide="split"></i><strong>Due percorsi</strong><span>Telemetria fino a 200 Hz / FFT da 1024 campioni</span></li><li><i data-lucide="database"></i><strong>Archivio locale</strong><span>Campioni, aggregati, configurazioni e note</span></li><li><i data-lucide="git-compare-arrows"></i><strong>Confronto</strong><span>Metriche descrittive e regole esplorative</span></li></ol>
<p><strong>Perche importa:</strong> un grafico telemetrico apparentemente liscio non dimostra che il segnale nativo fosse privo di rumore. La FFT riceve i frame prima del limite di visualizzazione; il grafico telemetrico, invece, puo perdere picchi molto brevi. La riduzione conserva un campione ogni almeno 5 ms: non e una media mobile e non applica un filtro antialias dedicato.</p>
<p>Per un archivio vecchio senza aggregati PID, la soluzione e reimportare il BBL originale. I dati nativi gia scartati non possono essere ricreati dal file sessione. I grafici sono generati localmente con uPlot; il decoder e derivato da Betaflight Blackbox Explorer, l'assetto usa Three.js e lo spettro usa fft.js.</p>${source(['src/import-worker.mjs','src/import-core.mjs','src/tuning.mjs'])}`},
{id:'importazione',title:'03 / Importazione, canali e scale',tags:'bbl bfl csv gyro acc voltage current high resolution',html:`
<h3>BBL / BFL nativo</h3><p>Il lettore cerca le intestazioni Blackbox, poi decodifica i frame I e P. Gli altri tipi di frame non alimentano le metriche correnti. Il parser accetta Betaflight dalla versione 3.1.0, ma questo non implica che le regole di suggerimento siano validate per tutte le versioni: Miglioramenti le abilita soltanto per la famiglia 4.3-4.5, oltre alla demo.</p>
<p>Il primo timestamp valido diventa lo zero del volo. Frame non validi, tempi non crescenti, tempi negativi o oltre 24 ore vengono esclusi. Alcuni errori invalidano il blocco spettrale o riavviano la stima d'assetto. Un file con piu voli puo produrre heat valide e messaggi di errore per i voli non leggibili.</p>
${table(['Dato','Normalizzazione nel lettore'],[
['Tempo','(time - primo time) / 1.000.000, in secondi.'],
['Setpoint Roll/Pitch/Yaw','setpoint[0..2], diviso per 10 se blackbox_high_resolution e attivo; velocita angolare richiesta, non angolo.'],
['Gyro','gyroADC[0..2] moltiplicato per gyroScale convertito da rad/us a deg/s e compensato per high-resolution. Senza intestazione di scala il canale resta assente.'],
['Gyro non filtrato','Solo gyroUnfilt[0..2], con la stessa conversione. I campi debug non vengono interpretati come gyro grezzo.'],
['Throttle','setpoint[3] / 10; in alternativa (rcCommand[3] / fattore high-resolution - 1000) / 10. Il risultato BBL e limitato a 0-100%.'],
['Motori','100 * (uscita - minimo) / (massimo - minimo), limitato a 0-100%. Senza limiti motorOutput validi le percentuali non sono disponibili. Non sono RPM o spinta.'],
['Batteria','vbatLatest / 100 da Betaflight 4.0, / 10 prima di 4.0. amperageLatest / 100 in ampere. Il tool non corregge sensori mal calibrati.'],
['Accelerometro','accSmooth / acc_1G, solo con riferimento 1 g valido.'],
['Contributi PID','axisP, axisI, axisD, axisF per i tre assi, nelle unita del log. Questi segnali non sono i guadagni P/I/D/F.']])}
<h3>CSV</h3><p>Papa Parse cerca una riga di intestazione tra le prime 1000 righe, con almeno due colonne e un nome temporale riconosciuto. Nomi duplicati sono rifiutati. Il mapping iniziale e un suggerimento: conferma colonne, tempo s/ms/us, scala gyro, throttle, limiti motore, divisori di tensione/corrente e riferimento accelerometro.</p>
<p>I campi vuoti diventano valori mancanti, non zero. Numeri con virgola decimale vengono convertiti quando correttamente racchiusi nel CSV. Throttle fuori 0-100% viene escluso; le uscite motore vengono limitate dopo la normalizzazione. Il CSV non recupera automaticamente le intestazioni di configurazione BBL: viene marcato "CSV / scale confermate" e non abilita le proposte firmware-specifiche di Miglioramenti.</p>
${note('Scale sbagliate = conclusioni sbagliate','Un errore tra microsecondi e millisecondi cambia durata e frequenza di campionamento. Una scala gyro errata cambia RMS, spettro e assetto. Prima di interpretare un suggerimento, verifica che ordini di grandezza e canali siano plausibili.')}
${source(['src/import-core.mjs','src/import-worker.mjs','vendor/src/flightlog_parser.js'])}`},
{id:'metriche',title:'04 / Metriche telemetriche: formule',tags:'rms tracking tensione consumo mah throttle saturazione copertura',html:`
<p>Le metriche di TELEMETRIA e CONFRONTO usano i campioni conservati all'interno del ritaglio della heat. Considerano coppie consecutive con intervallo positivo e non superiore a 100 ms. Un buco maggiore non viene attraversato dall'integrazione.</p>
${code('dt_i = t_i - t_(i-1)\nT_valido = somma(dt_i validi)\nmedia(x) = somma((x_(i-1) + x_i) / 2 * dt_i) / T_x\ne_i = setpoint_i - gyro_i\nRMS_tracking = sqrt(somma((e_(i-1)^2 + e_i^2) / 2 * dt_i) / T_e)')}
<p><code>T_x</code> e <code>T_e</code> includono soltanto coppie con entrambi i valori richiesti. Per questo due canali possono avere coperture differenti. L'assenza di un canale produce "--", non un risultato pari a zero.</p>
${table(['Metrica','Calcolo e lettura'],[
['Durata','Ultimo meno primo campione nel ritaglio. Non e necessariamente il tempo di volo armato e non e il tempo ufficiale della gara.'],
['Copertura','100 * T_valido / durata. Misura continuita temporale dei campioni conservati, non precisione del sensore.'],
['Throttle medio','Media trapezoidale pesata sul tempo. Non e una stima di velocita.'],
['Throttle >=80%','Durata delle coppie il cui primo campione ha throttle >=80%, divisa per il tempo con throttle valido. L\'indicatore di soglia non e interpolato nel punto di attraversamento.'],
['Variazione throttle','Somma |throttle_i - throttle_(i-1)| / tempo valido, in punti percentuali al secondo. Include variazioni intenzionali: piu basso non significa guida migliore.'],
['Motori >=95%','Quota del tempo con almeno uno dei quattro motori >=95% al primo campione della coppia. Richiede tutti i quattro canali. E un proxy di margine, non una misura di spinta residua.'],
['Tensione minima','Minimo campione di tensione disponibile nel ritaglio. Dipende anche da pacco, stato di carica, calibrazione e carico.'],
['Consumo integrato','Somma ((I_precedente + I_attuale)/2 * dt / 3,6), in mAh. Non ricostruisce la corrente negli intervalli mancanti.'],
['Tracking per asse','Scarto RMS tra comando e gyro. Un ritardo, un comando piu aggressivo, il rumore o una saturazione possono aumentarlo senza identificare una singola causa.']])}
${figure('tracking-chart','Comando e risposta: errore non significa causa','Il setpoint e una sinusoide da 120 deg/s a 3 Hz; la risposta illustrativa ha un ritardo variabile e rumore a 90 Hz. RMS calcolato sui segnali sintetici, non sul tuo volo.','<label class="figure-control">Ritardo illustrativo <input id="tracking-lag" type="range" min="0" max="50" step="1" value="15"><output id="tracking-output">15 ms</output></label>','<p class="figure-key"><span class="yellow">Setpoint</span><span class="cyan">Gyro illustrativo</span></p>')}
<p>Il tempo ufficiale viene parsato come secondi o mm:ss.mmm, maggiore di zero e fino a 24 ore. Il delta rispetto alla heat di riferimento e aritmetico e non viene usato dalle regole PID. Il sistema non calcola settori, posizione in classifica o punti del circuito.</p>${source(['src/model.mjs: metrics','src/app.mjs: renderTelemetry / renderCompare'])}`},
{id:'allineamento',title:'05 / Ritaglio e allineamento',tags:'percentuale secondi offset overlay tempo allineamento',html:`
<p>Nel confronto telemetrico ogni heat conserva il proprio ritaglio. Il riferimento e un'altra heat della sessione; sono mostrabili fino a quattro voli. L'asse orizzontale ha due significati alternativi:</p>
${code('Secondi: x = t - primo_campione_del_tratto + offset_heat\nPercentuale: x = 100 * (t - primo_campione) / durata_del_tratto')}
<p>In percentuale una heat di 80 s e una di 100 s terminano entrambe a 100%. Un picco al 50% puo corrispondere a manovre diverse. In secondi l'offset e manuale e ammesso tra -600 e +600 s. Il tool non identifica automaticamente gate, giri o manovre equivalenti.</p>
${figure('alignment-chart','Stessa percentuale, tempi diversi','Due tratti di 80 e 100 secondi. Gli eventi esemplificativi sono a 40 e 50 secondi: coincidono al 50%, ma non provano il passaggio nello stesso punto.','<fieldset class="figure-modes"><legend>Asse del confronto</legend><label><input type="radio" name="align-mode" value="seconds" checked> Secondi</label><label><input type="radio" name="align-mode" value="percent"> Percentuale</label></fieldset>')}
<p>I grafici telemetrici riducono ulteriormente il disegno a circa 1800 punti per serie, con estremi e discontinuita. Lo zoom cambia l'inquadratura, non il ritaglio usato dalle metriche. Le curve non uniscono buchi oltre 100 ms. Il grafico motori medio richiede tutti i quattro motori al campione.</p>${source(['src/app.mjs: drawCharts','src/model.mjs: samplesFor'])}`},
{id:'assetto',title:'06 / Assetto 3D e orientamento',tags:'quaternion roll pitch yaw gyro accelerometro deriva 3d',html:`
<p>Il quad-X del replay e un modello generico: rappresenta l'orientamento, non la traiettoria, la geometria esatta del tuo telaio o la posizione dei gate. I modelli sovrapposti condividono volutamente lo stesso centro.</p>
${table(['Fonte mostrata','Come viene ottenuta','Limite'],[
['REGISTRATO','Tre componenti imuQuaternion divise per 32767; w = sqrt(max(0, 1-x^2-y^2-z^2)); normalizzazione. Somma dei quadrati oltre 1,001 rifiutata.','Dipende dai dati e dalle convenzioni del firmware.'],
['STIMATO / GYRO + ACC','Stima complementare vendorizzata da Blackbox Explorer, alimentata prima della riduzione a 200 Hz.','Non e una riproduzione esatta dell\'estimatore della FC moderna. Accelerazioni di manovra possono contaminare il riferimento gravitazionale.'],
['ROT. RELATIVA / GYRO','Integrazione quaternionica della velocita angolare media tra due frame; orientamento iniziale convenzionale.','Nessuna inclinazione o direzione assoluta garantita; deriva nel tempo.'],
['ROT. RELATIVA / ARCHIVIO','Fallback sui campioni gia conservati quando non ci sono orientamenti validi.','Puo perdere rotazioni rapide non rappresentate nel campionamento ridotto.'],
['SIMULATO','Orientamento costruito per la demo.','Non deriva da un volo reale.']])}
<h3>Stima complementare, passo per passo</h3><p>L'inizializzazione con accelerometro richiede modulo tra 0,85 e 1,15 g. La routine IMU ruota il vettore di gravita stimato tramite il gyro; quando il modulo quadrato normalizzato dell'accelerazione e tra 0,72 e 1,33, combina vettore precedente e misura con pesi 600/601 e 1/601. Questo peso e per aggiornamento, non una costante di tempo universale indipendente dalla frequenza. Non viene usato un magnetometro per correggere lo yaw.</p>
<p>Un gyro mancante invalida la stima; un'interruzione oltre 100 ms riavvia il riferimento e incrementa il segmento. Nel replay l'interpolazione SLERP segue il percorso quaternionico piu breve, ma non attraversa buchi oltre 100 ms, segmenti differenti o estremi privi di assetto. Throttle e motori vengono interpolati linearmente quando presenti.</p>
${figure('attitude-chart','Tre rotazioni, non tre spostamenti','Illustrazione ortografica semplificata del quad: roll attorno all\'asse longitudinale, pitch attorno al trasversale, yaw attorno al verticale. Le frecce non indicano una traiettoria.')}
<h3>Confronto A/B/C/D</h3><p>Ogni volo ha un punto comune scelto nel proprio log: tempo locale = tempo comune + ancora del volo. Sono ammessi tempi comuni negativi. Il range globale e l'unione dei ritagli traslati, quindi alcuni modelli possono risultare fuori intervallo. L'opzione di allineamento yaw rimuove la direzione iniziale all'ancora, senza correggere la deriva successiva. Se all'ancora non c'e un dato, il tool segnala yaw non allineato.</p>
<p>Gli angoli sono ricavati con ordine Euler ZYX; lo yaw visualizzato ha segno invertito rispetto alla componente z della convenzione interna. La trasformazione per Three.js e (qy, -qz, -qx, qw). Il DELTA A e la distanza angolare tra quaternioni, non la somma delle differenze roll/pitch/yaw e non una distanza spaziale. I grafici si interrompono quando un angolo attraversa il salto di rappresentazione di 180 gradi.</p>
<p>La riproduzione supporta 0,25x, 0,5x, 1x e 2x, passo manuale di 20 ms e loop. Cambiare la velocita di replay non cambia il volo o le metriche. L'interfaccia 3D richiede WebGL2; un problema grafico non implica necessariamente che manchino i dati.</p>${source(['src/attitude-model.mjs','vendor/src/imu.js','src/attitude-view.mjs','src/attitude-scene.mjs'])}`},
{id:'finestre',title:'07 / Finestre native e qualita',tags:'1024 campioni 2048 fs frequenza copertura scartati finestre',html:`
<p>L'analisi PID accumula blocchi consecutivi non sovrapposti di <strong>1024 campioni nativi</strong>. Una finestra termina al campione numero 1024 e la successiva ricomincia da zero, senza overlap.</p>
${code('dt_medio = (t_1023 - t_0) / 1023\nfs = 1 / dt_medio\nvincolo_temporale: |dt_i / dt_medio - 1| <= 0,05\ndurata_analizzata = somma(t_fine_finestra - t_inizio_finestra)')}
<p>Una finestra e rifiutata se fs non e tra 10 e 32000 Hz o se almeno un intervallo devia oltre il 5% dalla media. Righe/frame non validi possono svuotare il blocco corrente. Alla fine del file la coda con meno di 1024 campioni viene scartata. Il massimo e 2048 finestre: i campioni successivi incrementano gli scarti e attivano il segnale di troncamento. A 1 kHz corrisponde a circa 2097 s di campioni prima del limite; a 8 kHz a circa 262 s.</p>
${figure('windows-chart','Finestre valide, buco, coda incompleta','Schema illustrativo: il ritaglio include soltanto finestre complete. Blocchi interrotti o con tempi irregolari e code incomplete non entrano nella FFT. Nessuna interpolazione riempie il buco.')}
<p>Il ritaglio PID seleziona solo finestre interamente comprese tra inizio e fine, con tolleranza numerica di 1 microsecondo. Il filtro throttle opera sulla <strong>media della finestra</strong>: basso &lt;35%, medio 35-70% escluso 70, alto &gt;=70%. Non seleziona singoli campioni ad alto gas. La durata spettrale e la somma delle durate delle finestre, non l'intero intervallo esterno.</p>
<h3>Tre coperture da non confondere</h3><ul><li><strong>Telemetrica:</strong> tempo di coppie senza buchi / durata del ritaglio, sui campioni conservati.</li><li><strong>Nativa:</strong> 100 * (1 - discarded / seen). Il contatore seen riguarda i frame consegnati al collettore; non include necessariamente tutti i byte o frame corrotti scartati prima. Non e una percentuale di integrita dell'intero file.</li><li><strong>Spettrale:</strong> finestre con un canale completo e frequenza adeguata. Una finestra temporale valida puo non avere uno spettro gyro o D.</li></ul>
<p>In Miglioramenti, meno dell'80% di campioni nativi utilizzabili oppure analisi troncata sospendono le proposte. E una scelta prudenziale del tool, non una soglia Betaflight. Servono inoltre almeno tre finestre e almeno tre secondi analizzati. A 1 kHz, tre finestre durano 3,069 s; a 8 kHz ne servono molte di piu per raggiungere tre secondi.</p>${source(['src/tuning.mjs: TuningCollector / selectWindows','src/setup-model.mjs: buildSetup'])}`},
{id:'spettri',title:'08 / FFT, PSD e alta frequenza',tags:'fft psd hann spettro rumore frequenza aliasing',html:`
<p>Per ogni asse vengono calcolati, quando disponibili, spettri di gyro filtrato, gyro non filtrato e contributo D. Non si mescolano le loro unita: il gyro e in deg/s, D nelle unita originali del log. Lo spettro e disponibile soltanto per serie complete di 1024 valori finiti e frequenza almeno 500 Hz.</p>
<ol><li>Si sottrae la media della serie, per ridurre la componente continua.</li><li>Si applica la finestra Hann: w[n] = 0,5 - 0,5*cos(2*pi*n/(N-1)).</li><li>fft.js calcola la trasformata reale.</li><li>Si costruisce la PSD monolaterale: |X[k]|^2 * c / (fs * somma(w^2)), con c=2 tranne al bin di Nyquist, dove c=1.</li><li>Il bin zero viene escluso. Quattro bin consecutivi vengono mediati per ciascuna delle 128 bande esportate, preservando la potenza tramite la larghezza di banda nell'integrazione.</li></ol>
${code('N = 1024\npasso_bin = fs / 1024\nlarghezza_banda_aggregata = fs / 256\ncentro_banda_j = (2,5 + 4*j) * fs / 1024\npotenza_banda = somma(PSD_j * fs / 256)\nRMS_HF = sqrt(potenza tra 100 Hz e min(1000 Hz, 0,45*fs))')}
${figure('spectrum-chart','Due frequenze note nello spettro','Segnale sintetico: sinusoide 30 Hz da 40 deg/s e 220 Hz da 12 deg/s, campionato a 1000 Hz. Il grafico usa la stessa funzione spectrum() del motore, non uno spettro decorativo. I picchi appaiono aggregati in bande da 3,90625 Hz.','', '<p class="figure-key"><span class="yellow">PSD gyro sintetica / (deg/s)^2/Hz</span></p>')}
<p>Per aggregare piu finestre si sceglie la frequenza minima e si includono nello spettro soltanto quelle entro l'1% di quel valore. La media PSD e pesata sulla durata. Le altre metriche temporali possono invece usare tutte le finestre selezionate: numero di finestre e numero di spettri possono quindi differire.</p>
<p>La percentuale HF del gyro e la potenza tra 100 Hz e min(1000 Hz, 0,45*fs) divisa per la potenza tra 0 e 0,45*fs. La stessa logica produce la percentuale HF del D. Il picco indicato e il centro della banda piu potente nel range HF, non la frequenza esatta di una risonanza. I bordi sono selezionati tramite i centri di banda, quindi l'integrazione e approssimata vicino ai limiti.</p>
${note('Cosa lo spettro non dimostra','Una componente sopra 100 Hz non e automaticamente un difetto meccanico. Un picco non identifica da solo motore, elica o telaio. Dati gia aliasati non si recuperano con una FFT; una frequenza di logging bassa puo mascherare rumore. Senza gyroUnfilt non si misura quanto rumore abbiano rimosso i filtri.')}
${source(['src/tuning.mjs: spectrum / frequencies / bandPower / summarizeTuning'])}`},
{id:'ritardo',title:'09 / Tracking, contributi e ritardo',tags:'lag correlazione pearson delay pid terms bias tracking',html:`
<p>Ogni finestra calcola RMS dell'errore setpoint-gyro, RMS del comando, RMS gyro e RMS dei contributi P/I/D/F. Il bias viene calcolato solo se il valore assoluto del setpoint resta sotto 30 deg/s in tutta la finestra. L'RMS aggregato e la radice della media, pesata nel tempo, degli RMS di finestra al quadrato. Il bias e la media pesata dei soli valori disponibili.</p>
<h3>Stima del ritardo apparente</h3><p>Si cerca uno spostamento positivo del gyro rispetto al setpoint che massimizzi la correlazione di Pearson. La stima richiede entrambi i segnali, fs almeno 500 Hz e deviazione standard del setpoint di almeno 30 deg/s. Senza movimento sufficiente una correlazione non e informativa.</p>
<p>La ricerca arriva fino al minore tra circa 60 ms e N/4 campioni. Il passo e circa 2 ms, arrotondato ad almeno un campione. Il confronto sottocampiona gli indici con passo 8 per N=1024 e usa la stessa porzione utile per ogni ritardo. Occorrono correlazione almeno 0,7 e un massimo non troppo vicino al limite superiore della ricerca (margine di 2 ms). Un ritardo positivo deve migliorare la correlazione di almeno 0,02 rispetto a lag zero; altrimenti la stima viene scartata. Zero puo essere una stima valida.</p>
<p>Il ritardo complessivo e la media pesata dei ritardi accettati, non la correlazione dell'intero volo. Include dinamica del mezzo, comando, filtri e altri effetti; non isola il ritardo di un singolo filtro. Non vengono cercati anticipi negativi.</p>
${note('Guadagno e contributo sono diversi','P=50 nella configurazione e un coefficiente. RMS P=50 nel log e una misura dell\'uscita del termine durante quel tratto. Non sono intercambiabili e non vanno confrontati direttamente come se avessero lo stesso significato.')}
${source(['src/tuning.mjs: lagEstimate / summarizeTuning'])}`},
{id:'regole',title:'10 / Tutte le regole dei suggerimenti',tags:'soglie consigli tuning noise d-noise tracking saturation bias',html:`
<p>Le regole sono deterministiche e leggibili nel sorgente: non c'e un modello AI che ottimizza il volo, ne un identificatore completo della dinamica del quad. Le soglie sotto sono criteri esplorativi dell'applicazione, non prescrizioni ufficiali del firmware.</p>
${table(['Regola','Condizioni effettive','Indicazione prodotta'],[
['Dati mancanti / tratto corto','Report assente, oppure durata &lt;3 s o meno di 3 finestre.','Reimportare il log originale o estendere il tratto; nessuna modifica deducibile.'],
['Margine motori ignoto','Saturazione non calcolabile per canali/scale assenti.','Non valutare aumenti di guadagno senza verificare il margine.'],
['Saturazione','Almeno 5% del tempo di finestra con un motore >=95%.','Controllare batteria, eliche, peso e limiti di uscita prima di aumentare PID.'],
['Spettro assente','Gyro non disponibile o frequenza insufficiente per lo spettro.','Non alleggerire i filtri sulla base di questi dati.'],
['Residuo gyro HF','RMS HF >=5 deg/s e quota HF >=30%.','Controllo meccanico; se si ripete, valutare maggiore filtraggio gyro. Non e diagnosi di risonanza.'],
['Gyro grezzo assente','Spettro gyroUnfilt non disponibile.','Confronto prima/dopo filtraggio incompleto. Non reinterpretare automaticamente debug.'],
['D assente','RMS del contributo D mancante.','Verificare registrazione o D disabilitato. Non proporre aumento D o riduzione del filtraggio D.'],
['D dominato da HF','Quota HF D >=40%; RMS P disponibile; RMS D > max(5, 1,5 * RMS P).','Dopo la verifica meccanica, valutare maggiore filtraggio D, senza aumentare D per compensare il rumore.'],
['Tracking in ritardo','Guadagni dell\'asse presenti nelle intestazioni; contributo P presente; saturazione &lt;5%; spettro gyro presente; RMS HF &lt;5; errore RMS > max(20, 0,2 * RMS comando); lag >=10 ms su almeno 3 finestre correlate.','Ipotesi P/Feedforward da distinguere. Una piccola variazione del solo P e una prova, non una soluzione calcolata.'],
['Bias persistente','Margine motori verificabile con saturazione &lt;5% e |bias medio| >10 deg/s nelle finestre a comando piccolo.','Controllare vento, bilanciamento, orientamento FC e I-term. Non equivale a I insufficiente.'],
['Mantieni riferimento','Nessuna delle regole noise, d-noise, tracking, saturation o bias e attiva.','Nessuna modifica motivata. Possono comunque esserci avvisi su dati mancanti.']])}
<h3>Ordine della prossima prova</h3><p>Miglioramenti controlla prima configurazione discordante, qualita e sufficienza del tratto/versione. Poi cerca, in ordine: saturazione, margine motori ignoto, spettro assente, rumore gyro, rumore D, tracking, bias. Per una stessa categoria sceglie il primo asse nell'ordine Roll, Pitch, Yaw: non necessariamente l'asse con valore massimo. Le altre evidenze restano consultabili nelle righe e in PID / FILTRI.</p>
<p>La sezione PID / FILTRI mostra gli indizi del motore analitico; Miglioramenti applica ulteriori blocchi per firmware, qualita e backup. Vedere un indizio nella prima sezione e "proposte sospese" nella seconda non significa che la sospensione vada ignorata. Un avviso generale di rumore puo esistere anche senza un parametro attivo/modificabile identificato.</p>${source(['src/tuning.mjs: tuningAdvice','src/setup-model.mjs: buildSetup / nextTrial'])}`},
{id:'filtraggio',title:'11 / Come leggere "piu filtraggio"',tags:'filtri lowpass cutoff slider 90 180 min max rumore',html:`
<p><strong>Per un lowpass, piu filtraggio significa generalmente abbassare la frequenza di taglio, non alzarla.</strong> Negli slider filtri Betaflight una riduzione del moltiplicatore sposta i cutoff verso valori inferiori. Il beneficio possibile e una maggiore attenuazione del rumore, con un costo in ritardo. Questo principio non autorizza a ridurre indiscriminatamente ogni valore in Hz di ogni filtro.</p>
${figure('filter-chart','Lowpass: attenuazione e frequenza di taglio','Modello analogico ideale PT1 a un polo, solo didattico: |H(f)| = 1/sqrt(1+(f/fc)^2). Non replica l\'intera catena digitale Betaflight, il filtro dinamico o una Blackbox. Alla frequenza di taglio il guadagno vale circa 0,707.','<label class="figure-control">Cutoff illustrativo <input id="filter-cutoff" type="range" min="40" max="300" step="5" value="90"><output id="filter-output">90 Hz</output></label>','<p class="figure-key"><span class="yellow">Cutoff selezionato</span><span class="cyan">Riferimento 180 Hz</span></p>')}
<p>Min e Max delimitano la variazione del cutoff nel filtro dinamico. Abbassare Min influenza soprattutto la zona inferiore della curva; Max la zona superiore, ma il comportamento esatto dipende da versione e impostazioni della curva. Il tool non ricostruisce l'intera curva dal throttle e non localizza automaticamente quale estremo vada modificato.</p>
${note('Esempio 90 / 180 Hz','Se entrambi i campi sono evidenziati, non sono due ordini indipendenti. L\'attuale regola puo propagare lo stesso indizio di rumore a entrambi gli estremi. 90/180 non vengono trasformati automaticamente in una nuova coppia consigliata. Controlla se sei nella famiglia Gyro o D Term e apri la motivazione.')}
<ol><li>Verifica eliche, motori e fissaggio FC prima della modifica software.</li><li>Conserva il backup della configurazione del volo.</li><li>Identifica famiglia, tipo di filtro e modalita di regolazione realmente attiva nel Configurator.</li><li>Scegli un solo percorso: slider della famiglia interessata oppure controllo manuale mirato. Non combinare nella stessa prova modifiche a slider, entrambi i cutoff e PID.</li><li>Ripeti una prova breve e confrontabile. Verifica rumore, tracking, oscillazioni, risposta nelle manovre e temperatura motori; interrompi se il comportamento e anomalo.</li><li>Documenta il cambiamento e confronta il nuovo log. Un rumore inferiore con risposta peggiore non e automaticamente un risultato utile.</li></ol>
<p>RPM e dynamic notch sono famiglie diverse: numero armoniche, Q e frequenza minima non obbediscono tutti alla regola "abbassa gli Hz". In questa versione il tool mostra quei valori ma non calcola un'ottimizzazione specifica dei notch. <a href="https://betaflight.com/docs/wiki/app/pid-tuning-tab" target="_blank" rel="noopener">Riferimento ufficiale: scheda PID e filtri</a>.</p>${source(['src/setup-model.mjs: advice noise / d-noise','src/setup-view.mjs: proposal / showDetails'])}`},
{id:'configurazione',title:'12 / Attuale, consigliato e provenienza',tags:'configurazione attuale consigliato log cli alias zero non disponibile',html:`
<p>La colonna attuale e una lettura, non un controllo connesso alla FC. I campi disabilitati e gli slider in sola lettura non cambiano il mezzo. Il motore cerca intestazioni esplicite, accetta numeri finiti non negativi e conserva la chiave originale. Zero e un valore valido: non equivale a dato mancante e il suo significato dipende dal parametro.</p>
${table(['Stato','Significato operativo'],[
['BLACKBOX','Valore numerico letto dal log: fonte primaria quando disponibile.'],
['BACKUP CLI','Valore esplicito riconosciuto nel backup confermato, usato per colmare un dato mancante e solo con versione firmware esatta corrispondente.'],
['Non disponibile','Il dato non e presente o non e interpretabile con la mappatura corrente; non viene sostituito con il default del firmware.'],
['Valori discordanti','Alias dello stesso dato diversi, oppure backup e log incompatibili per un campo riconosciuto. Il log non viene sovrascritto.'],
['Invariato nella proposta','Nessuna modifica specifica motivata dalle regole. Il numero ripetuto non e un valore ottimo certificato.'],
['Piu filtraggio / aumento da valutare','Direzione esplorativa con evidenza; il valore numerico di destinazione non e calcolato.'],
['Dati insufficienti / versione da verificare','I valori possono essere consultati, ma non ci sono condizioni per una proposta.'],
['Proposte sospese','Blocchi di qualita o configurazione impediscono di presentare il valore come proposta utilizzabile.']])}
<p>Le modifiche di riga sono limitate a P in presenza dell'indizio tracking e a slider/min/max dinamici gyro o D in presenza degli indizi di rumore. Il valore attuale deve essere maggiore di zero. I, D, Feedforward, TPA, notch, tipi di filtro e altri campi sono consultabili ma non ricevono una nuova taratura numerica automatica. Lo stato "invariato" di questi campi non significa che siano stati ottimizzati.</p>
<p>D dinamico e chiamato D Max solo quando il log contiene esplicitamente <code>d_max</code>; altrimenti viene cercato <code>d_min</code>. Non vengono trattati come alias indistinguibili. Gli slider moltiplicatore sono visualizzati dividendo per 100; non vengono ricostruiti a ritroso dai guadagni. Tipi filtro noti: PT1, BIQUAD, PT2, PT3; modalita PID: OFF, RP, RPY. Codici non riconosciuti non vengono indovinati.</p>${source(['src/setup-model.mjs: readSetting / SETUP_GROUPS / buildSetup','src/setup-view.mjs'])}`},
{id:'backup',title:'13 / Backup CLI, profili e storico',tags:'diff dump profili history default import cli',html:`
<p><code>diff all</code> e <code>dump</code> sono acquisiti come testo, non eseguiti. In particolare <code>defaults nosave</code> e <code>save</code> non producono azioni. Il diff contiene differenze rispetto ai default, quindi non e una fotografia esplicita di ogni parametro. Il dump puo essere piu completo. <a href="https://betaflight.com/docs/wiki/guides/current/Profiles" target="_blank" rel="noopener">Riferimento Betaflight sui profili e backup</a>.</p>
<p>Il parser legge righe <code>set nome = valore</code>, ignora righe vuote/commenti e separa i profili PID. <code>rateprofile</code> apre un ambito che viene escluso dalle letture PID fino al successivo <code>profile</code>. Le impostazioni prima di un profilo sono master; per un file senza profili numerati la scelta e "profilo corrente / non numerato". Non viene dedotto automaticamente quale profilo fosse attivo dal solo ultimo comando del backup.</p>
${code('# Esempio didattico, NON preset da applicare\n# Betaflight / TARGET 4.5.0\nset gyro_lpf1_dyn_min_hz = 250\nprofile 0\nset p_roll = 46\nprofile 1\nset p_roll = 60\nprofile 0\nsave')}
<p>Nell'esempio, selezionare CLI 0 significa leggere P roll 46, non 60. L'interfaccia ricorda che CLI 0 corrisponde al profilo 1 del Configurator. Il ritorno finale a profile 0 non cancella le assegnazioni gia lette. Se lo stesso parametro nello stesso ambito compare con valori differenti, viene marcato come conflittuale invece di accettare silenziosamente l'ultimo.</p>
<p>Il lettore riconosce guadagni per asse (<code>p_roll</code>, <code>i_roll</code>, <code>d_roll</code>, <code>f_roll</code> e analoghi), alcuni enum e i nomi espliciti dei filtri. Non interpreta ogni possibile comando o enum di ogni firmware. Dati non riconosciuti restano nel backup originale scaricabile, ma non vengono usati per riempire le tabelle.</p>
<p>La versione completa, incluso eventuale suffisso prerelease riconosciuto, deve coincidere con quella del log. Versione assente, diversa o backup reale associato alla demo sospendono la compatibilita. Una conferma del pilota attesta che file e profilo sono quelli usati in volo; il tool non verifica seriale FC, hash di configurazione completa o data effettiva del volo.</p>
<p>Ogni heat conserva il backup corrente e fino a quattro precedenti. Associare un nuovo file archivia quello attuale; scollegarlo lo archivia e torna ai soli dati Blackbox. Oltre quattro precedenti, il piu vecchio esce dallo storico locale: scaricalo prima. Scaricare un backup non ripristina la FC e non rende sicuro applicarlo a un firmware diverso.</p>${source(['src/config-backup.mjs','src/setup-model.mjs','src/model.mjs: validateSession'])}`},
{id:'prima-dopo',title:'14 / Prima e dopo: cosa confrontiamo',tags:'confronto ab delta causalita condizioni setup meteo',html:`
<p>La heat attuale e il DOPO; il menu sceglie il PRIMA anche da un'altra sessione. Non viene verificato che l'ordine sia cronologico. Il DOPO usa il tratto e la selezione throttle della pagina; il PRIMA usa il proprio ritaglio salvato e la stessa categoria throttle. Non c'e corrispondenza automatica tra punti del percorso.</p>
<p>Il confronto riporta tracking RMS, residuo gyro HF e ritardo apparente per asse, piu le differenze dei parametri numerici presenti in entrambe le configurazioni. Un campo assente da un lato non e considerato uguale, zero o modificato. Nessuna differenza tra i parametri disponibili non prova che due configurazioni complete siano identiche.</p>
${table(['Condizione di cautela','Controllo attuale'],[
['Tratto / qualita','Almeno 3 finestre e 3 s per entrambi; assenza di troncamento, copertura bassa e blocchi di configurazione.'],
['Origine / firmware','Origine report e stringa firmware uguali; firmware supportato. Non confrontare demo e reale.'],
['Setup','Confronto della descrizione testuale del setup; non riconoscimento automatico dell\'hardware.'],
['Throttle','Avviso se le medie differiscono di oltre 10 punti percentuali, quando entrambe disponibili.'],
['Intensita del comando','Per ogni asse: |RMS_dopo - RMS_prima| > max(20 deg/s, 25% di RMS_prima) produce avviso.'],
['Frequenza','Frequenze minime assenti o diverse oltre 1% producono avviso; non si confrontano bande diverse come equivalenti.'],
['Conferma pilota','Checkbox sullo stesso mezzo, percorso e condizioni. Non e una verifica automatica di meteo, batteria o traiettoria.']])}
<p>Un solo avviso sospende tutti i delta nella tabella. Anche senza avvisi, i delta restano nascosti finche non confermi la comparabilita. Quando ammessi: delta = DOPO - PRIMA, in unita assolute, non percentuali. Un valore negativo di rumore o errore descrive una riduzione, non dimostra la causa o il vantaggio in gara.</p>
<p>Le note di prova e condizioni sono salvate sulla heat. La selezione del riferimento e la checkbox sono locali alla vista e vanno ricontrollate dopo un cambio pagina; non diventano una dichiarazione permanente di comparabilita. L'esportazione del confronto include ambiti, evidenze, parametri e note, e non esporta comandi CLI da applicare.</p>
${note('Meteo e causalita','Temperatura, pressione e umidita non sono attualmente un modello di compensazione PID. Puoi annotarle, ma il tool non calcola densita dell\'aria o nuovi guadagni per condizioni future. Vento, batteria ed eliche possono cambiare il risultato e non sono isolati automaticamente.')}${source(['src/setup-model.mjs: compareSetups','src/setup-view.mjs: comparison / exportComparison'])}`},
{id:'dizionario',title:'15 / Dizionario completo dei parametri',tags:'parametri nomi alias p i d feedforward tpa filtri',html:`
<p>La matrice guadagni legge P/I/D dalle tre posizioni di <code>rollPID</code>, <code>pitchPID</code>, <code>yawPID</code>; Feedforward da <code>feedforward_weight</code> per asse; D dinamico da <code>d_max</code> o <code>d_min</code>. Nel backup CLI usa p_/i_/d_/f_ seguiti dall'asse. P reagisce all'errore corrente, I all'accumulo dell'errore, D alla variazione del segnale e F al comando: questa descrizione concettuale non sostituisce l'implementazione del controller della tua versione.</p>
<p>Le tabelle seguenti sono generate dalla stessa definizione usata in Miglioramenti. Elencano <strong>tutti i campi attualmente esposti e gli alias Blackbox cercati</strong>. Non sono un elenco di parametri tutti modificabili automaticamente. Nomi e unita non riconosciuti restano consultabili solo nel backup originale.</p>
${SETUP_GROUPS.map(g=>`<h3>${g.title}</h3>${table(['Campo','Intestazioni / alias letti','Formato e proposta'],g.fields.map(f=>[f.label,f.keys.map(k=>`<code>${k}</code>`).join('<br>'),`${f.index!==undefined?`Componente ${f.index} (indice da zero). `:''}${f.kind==='multiplier'?'Valore / 100, visualizzato in x.':f.kind==='filter'?'Tipo filtro enumerato.':f.kind==='mode'?'Modalita OFF/RP/RPY.':f.unit||'Valore nelle unita/codici del firmware.'} ${f.advice?'Direzione di filtraggio solo con evidenza, valore >0 e controlli superati.':'Nessuna nuova taratura numerica calcolata.'}`]))}`).join('')}
<h3>Relazioni tra gruppi</h3><p>Gli slider semplificati descrivono una modalita di regolazione dei guadagni, non contributi misurati. Feedforward, I Term Relax, Anti Gravity, Dynamic D e TPA introducono dipendenze dai comandi e dalle condizioni: leggere il guadagno base non descrive necessariamente l'azione istantanea. LPF attenuano una banda alta; notch e RPM mirano a componenti piu selettive. Il tool non simula l'intera catena controller-motori-eliche ne identifica automaticamente la causa di un picco.</p>${source(['src/setup-model.mjs: SETUP_GROUPS','src/config-backup.mjs: readBackupField'])}`},
{id:'archivio',title:'16 / Archivio, esportazioni e privacy',tags:'indexeddb localstorage export restore sessione privacy backup json csv',html:`
<p>Le sessioni sono salvate in IndexedDB nel database <code>gnd-race</code>, store <code>sessions</code>. Le preferenze del confronto d'assetto sono in localStorage (<code>gnd-attitude-v1</code>). Il parsing e i grafici avvengono nel browser; il codice dell'app non invia i log a un backend di analisi. Il provider di hosting riceve comunque le normali richieste per servire pagina e risorse, e i link esterni aprono siti terzi.</p>
<p>I dati appartengono all'origine web: sito attuale, localhost e dominio GitHub Pages hanno archivi distinti. Cambiare sottopercorso sullo stesso dominio non crea automaticamente un archivio isolato. Navigazione privata, cancellazione dati del browser, quote esaurite o un altro dispositivo possono impedire di ritrovare i voli. Non c'e sincronizzazione cloud.</p>
${table(['Esportazione','Contenuto','Uso'],[
['Sessione .gnd.json / v4','Campioni conservati, aggregati PID, metadati, orientamenti, backup corrente/storico e note.','Backup e trasferimento del lavoro. Non include il file BBL originale completo.'],
['Metriche CSV','Riepilogo delle metriche delle heat.','Analisi in foglio di calcolo; non sostituisce la sessione ripristinabile.'],
['Report PID JSON','Ambito, asse, configurazione, aggregati e indizi.','Documentare una lettura analitica.'],
['Confronto Miglioramenti JSON / v2','Valori, fonti, motivazioni, qualita, priorita, backup e confronto eventuale.','Documentare la proposta; recommended e null quando non c\'e un valore numerico validato.'],
['Backup CLI originale','Testo associato dal pilota, non riscritto come nuovo preset.','Conservazione della configurazione; ripristino FC sempre esterno al tool.'],
['Sorgenti ZIP','Codice, dipendenze dichiarate, test, licenze e sito.','Ricompilazione e pubblicazione. Non contiene il tuo IndexedDB.']])}
<p>Il ripristino della sessione accetta versioni 1-4, assegna nuovi ID e crea una copia separata. Verifica timestamp strettamente crescenti, intervalli, valori finiti, quaternioni, struttura degli spettri e backup CLI. Un file JSON non valido viene rifiutato, non eseguito. Non vengono importati come fidati valori di configurazione gia "interpretati": il backup resta testo da leggere di nuovo.</p>
<p>L'eliminazione di una heat/sessione richiede conferma ma non ha un cestino nell'app. Una copia esportata e il modo per recuperarla. I salvataggi sono accodati; un messaggio di errore non deve essere ignorato. L'archivio sorgenti e la demo sono pubblicabili, mentre Blackbox, backup FC e sessioni personali non devono essere inclusi nel repository pubblico.</p>${source(['src/storage.mjs','src/model.mjs: validateSession','src/app.mjs: persist / exportSession'])}`},
{id:'limiti',title:'17 / Limiti, errori e casi particolari',tags:'limiti troubleshooting errori demo firmware meteo gps dvr',html:`
${table(['Vincolo','Valore / comportamento'],[
['File BBL / CSV','Massimo 64 MiB per file nel worker.'],['Voli nello stesso BBL','Massimo 100 intestazioni di volo.'],['Campioni BBL conservati','Massimo 300.000 per volo; frequenza conservata al massimo circa 200 Hz.'],['CSV','Contatore limitato a 2 milioni di righe inclusa la riga iniziale di intestazione.'],['Sessione importata','Massimo 160 MiB, 100 heat e 2 milioni di campioni totali conservati.'],['Tempo','Intervallo di timestamp entro 24 ore; ordine strettamente crescente.'],['Analisi PID','1024 campioni per finestra, massimo 2048 finestre. Spettri da 500 Hz; banda HF fino a min(1000 Hz, 0,45*fs).'],['Backup CLI','Massimo 128 KiB in upload; ulteriore limite a 131.072 caratteri nel parser. Profilo numerico 0-9 ammesso dal parser, non garanzia che ogni firmware esponga dieci profili.'],['Storico backup','Corrente piu quattro precedenti per heat.'],['Confronti','Massimo quattro modelli/serie nel confronto principale; Prima/dopo confronta due heat.'],['Suggerimenti Miglioramenti','Famiglie firmware 4.3-4.5; almeno 3 finestre/3 s; qualita e configurazione coerenti.']])}
<h3>Diagnosi rapida</h3><dl class="guide-dl"><dt>"Non disponibile"</dt><dd>Verifica che il canale/parametro sia registrato e riconosciuto. Un diff puo ometterlo perche e al default. Non sostituire il vuoto con zero.</dd><dt>"Reimporta la Blackbox"</dt><dd>L'archivio potrebbe essere precedente all'analisi nativa. Reimporta il file originale: il riepilogo ridotto non basta.</dd><dt>"Dati insufficienti" dopo un ritaglio</dt><dd>Il tratto esterno puo sembrare lungo ma contenere poche finestre complete, oppure nessuna nella fascia throttle scelta.</dd><dt>Spettro vuoto</dt><dd>Verifica gyro, scala e frequenza >=500 Hz. Per D verifica che il contributo sia registrato. Per il grezzo serve gyroUnfilt.</dd><dt>Backup discordante</dt><dd>Ricontrolla versione, profilo e momento di acquisizione; non forzare il backup a prevalere sul log.</dd><dt>Assetto assente o che riparte</dt><dd>Controlla buchi, gyro/acc mancanti e attesa di inizializzazione vicino a 1 g. Il riferimento dopo un'interruzione puo essere nuovo.</dd><dt>"Nessuna modifica motivata"</dt><dd>Le regole non hanno isolato una prova, oppure non esistono campi applicabili. Non equivale a un mezzo perfetto o sicuro.</dd></dl>
<p>Non sono implementati: ricostruzione della traiettoria, mappa del circuito, sincronizzazione DVR, rilevamento giri/settori/classifica, modello meteo per riadattare i PID, temperatura motori ricavata dal log o identificazione automatica completa della dinamica. Il 3D non cambia questi limiti. I dati demo sono sintetici e non vanno trattati come prova di validazione su hardware.</p>
<p>Il tool e stato verificato con test deterministici, segnali sintetici e fixture di importazione. La correttezza su una Blackbox reale specifica va controllata confrontando scala, firmware e configurazione con Betaflight. Il supporto del decoder non equivale alla validazione dei suggerimenti.</p>`},
{id:'github',title:'18 / Pubblicare su GitHub Pages',tags:'github pages deploy pubblicazione installazione dominio migrazione',html:`
<p>Il sito e statico: non richiede database remoto, API key o server Node in produzione. Node e pnpm servono per ricompilare; in produzione vengono serviti solo i file in <code>dist</code>. Percorsi relativi e navigazione con hash permettono l'uso anche sotto <code>/nome-repository/</code>.</p>
<ol><li>Estrai il pacchetto GitHub preparato. La radice del repository deve contenere <code>package.json</code>, <code>src</code>, <code>dist</code> e <code>.github/workflows/pages.yml</code>, non un ulteriore livello di cartella.</li><li>Crea il tuo repository e carica i file, inclusa la cartella nascosta <code>.github</code>. Escludi sempre file personali, credenziali, <code>node_modules</code>, <code>.git</code> e dati di volo.</li><li>In Settings / Pages seleziona <strong>GitHub Actions</strong> come sorgente. Non selezionare <code>dist</code> dal menu branch: quel metodo espone root o docs, mentre il workflow carica dist come artefatto.</li><li>Il workflow parte su push a <code>main</code> o manualmente. Se usi un altro branch, modifica il filtro del workflow e le regole dell'ambiente GitHub Pages.</li><li>La build installa le dipendenze dal lockfile, esegue i test, ricompila app e guida, prepara i sorgenti scaricabili e pubblica l'artefatto statico. Un test fallito interrompe la pubblicazione.</li><li>Attendi il completamento in Actions e apri l'URL restituito dal job deploy. Controlla importazione, worker, 3D e guida sul dispositivo che userai in campo.</li><li>Esporta le sessioni dal vecchio dominio e reimportale sul nuovo. Non verranno trasferite dal repository.</li></ol>
<p>La disponibilita di Pages e la visibilita del sito dipendono dal piano e dalle impostazioni GitHub: non assumere che un repository privato renda automaticamente privato il sito. La configurazione di accesso del precedente hosting non viene trasferita. <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/using-custom-workflows-with-github-pages" target="_blank" rel="noopener">Workflow ufficiali GitHub Pages</a>.</p>
<h3>Solo file pronti, senza build</h3><p>Nel pacchetto sono inclusi anche i file compilati. Puoi pubblicare il contenuto di dist dalla radice di un branch dedicato, includendo <code>.nojekyll</code>. In quel caso non usare contemporaneamente il workflow di build: scegli un metodo di pubblicazione. Non basta caricare soltanto index.html; servono JS, worker, CSS, guida, licenze e sorgenti scaricabili.</p>
<h3>Sviluppo e verifica locale</h3>${code('pnpm install --frozen-lockfile\npnpm test\npnpm build\npnpm dev')}
<p>Apri l'indirizzo stampato dal server. Un doppio clic sul file HTML non riproduce correttamente le condizioni HTTPS del sito e puo impedire l'uso dei worker. Il pacchetto include <code>GITHUB_PAGES.md</code> con procedura, requisiti e risoluzione degli errori comuni.</p>`},
{id:'fonti',title:'19 / Fonti, codice e glossario',tags:'fonti glossario licenze audit algoritmi gpl',html:`
<p>Questo manuale descrive la versione di GND Race predisposta il 3 novembre 2026. Le soglie operative sono quelle del codice incluso, non raccomandazioni universali. Per un audit conserva insieme sessione esportata, Blackbox originale, backup FC e versione del progetto.</p>
${table(['Termine','Significato nel tool'],[['Setpoint','Velocita angolare richiesta in deg/s; non orientamento.'],['Gyro','Velocita angolare misurata.'],['RMS','Radice della media dei quadrati; misura ampiezza, non segno.'],['Bias','Media con segno dell\'errore nelle finestre a comandi piccoli.'],['PSD','Densita di potenza per Hz; l\'area integrata rappresenta potenza.'],['HF','Banda definita dall\'app da 100 Hz al limite specificato, non definizione universale di rumore.'],['Cutoff','Frequenza caratteristica del filtro; non confonderla con frequenza di logging.'],['Lag','Ritardo apparente stimato tramite correlazione.'],['SLERP','Interpolazione sferica tra orientamenti quaternionici.'],['Origin','Schema, dominio e porta che identificano l\'archivio browser.']])}
<h3>Riferimenti primari</h3><ul><li><a href="https://betaflight.com/docs/development/Blackbox-Internals" target="_blank" rel="noopener">Betaflight: struttura dei log Blackbox</a>.</li><li><a href="https://betaflight.com/docs/wiki/app/pid-tuning-tab" target="_blank" rel="noopener">Betaflight: scheda PID Tuning e filtri</a>.</li><li><a href="https://betaflight.com/docs/wiki/guides/current/Profiles" target="_blank" rel="noopener">Betaflight: profili e backup</a>.</li><li><a href="https://github.com/betaflight/blackbox-log-viewer" target="_blank" rel="noopener">Sorgente upstream del decoder e IMU vendorizzati</a>; gli hash della copia inclusa sono in vendor/SHA256SUMS.json.</li><li><a href="https://github.com/indutny/fft.js" target="_blank" rel="noopener">fft.js</a> per la trasformata, <a href="https://threejs.org/docs/" target="_blank" rel="noopener">Three.js</a> per orientamenti e scena.</li><li><a href="https://docs.github.com/en/pages/getting-started-with-github-pages/using-custom-workflows-with-github-pages" target="_blank" rel="noopener">GitHub Pages: pubblicazione con Actions</a>.</li></ul>
<p>Il codice dell'applicazione e distribuito GPL-3.0-or-later, senza garanzia. Mantieni LICENSE, attribuzioni, commenti legali dei bundle e sorgenti corrispondenti quando distribuisci il sito. Le librerie mantengono le proprie licenze, elencate nel README. <a href="./source.zip" download>Scarica il codice sorgente completo</a>.</p>`}
];

